// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    Receiver ownerRecv;

    function setUp() public {
        ownerRecv = new Receiver();
        vm.prank(address(ownerRecv));
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 balance, uint256 value) public {
        balance = bound(balance, 1, 100 ether);
        vm.assume(value > balance);
        vm.deal(address(c), balance);

        vm.prank(address(ownerRecv));
        (bool ok, ) = address(c).call(abi.encodeWithSelector(SimpleWallet.withdraw.selector, value));

        // Rule: withdrawing more than the funded balance must always revert.
        assertTrue(!ok);
    }
}

contract Receiver {
    receive() external payable {}
}
